"""log_returns spine: simple daily returns from the mdata.Prices sample."""

from __future__ import annotations

import pytest

from mdata import Prices
from risk.returns import log_returns
from risk.types import Returns


def prices_of(payload: dict) -> Prices:
    return Prices(
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        closes={t: tuple(c) for t, c in payload["closes"].items()},
    )


def test_sample_gives_returns_dated_after_the_base_date(contract_sample):
    returns = log_returns(prices_of(contract_sample("mdata.Prices")))
    assert isinstance(returns, Returns)
    assert returns.base_date == "2024-01-02"
    assert returns.dates == ("2024-01-03", "2024-01-04", "2024-01-05", "2024-01-08", "2024-01-09")
    assert returns.tickers == ("AAA", "BBB")
    assert set(returns.values) == {"AAA", "BBB"}


def test_sample_values_are_simple_returns(contract_sample):
    returns = log_returns(prices_of(contract_sample("mdata.Prices")))
    # AAA closes 100, 101, 99.5, 102, 103.5, 102.5
    assert returns.values["AAA"] == pytest.approx(
        (0.01, -1.5 / 101, 2.5 / 99.5, 1.5 / 102, -1.0 / 103.5), rel=1e-12
    )
    # BBB closes 50, 50.5, 51, 51.25, 52, 52.5
    assert returns.values["BBB"] == pytest.approx(
        (0.01, 0.5 / 50.5, 0.25 / 51, 0.75 / 51.25, 0.5 / 52), rel=1e-12
    )


def test_two_dates_give_one_return():
    prices = Prices(dates=("2024-01-02", "2024-01-03"), tickers=("X",), closes={"X": (4.0, 5.0)})
    returns = log_returns(prices)
    assert returns.base_date == "2024-01-02"
    assert returns.dates == ("2024-01-03",)
    assert returns.values == {"X": pytest.approx((0.25,))}


@pytest.mark.parametrize("dates", [(), ("2024-01-02",)])
def test_fewer_than_two_dates_is_an_error(dates):
    prices = Prices(dates=dates, tickers=("X",), closes={"X": (1.0,) * len(dates)})
    with pytest.raises(ValueError, match="at least two dates"):
        log_returns(prices)

